// Data de referencia em horario de Brasilia (BRT = UTC-3)
const now = new Date();
const brtOffset = -3 * 60 * 60 * 1000;
const brt = new Date(now.getTime() + brtOffset);
const dataRef = brt.toISOString().split('T')[0];

console.log('[IG] Iniciando analise do dia:', dataRef);

return [{ json: { data_referencia: dataRef } }];

const competitor = $input.first().json;
const dataRef = $('Set Data Referencia').first().json.data_referencia;

if (!competitor.username) {
  throw new Error('Concorrente sem username: ' + JSON.stringify(competitor));
}

console.log('[IG] Processando:', competitor.username, '|', competitor.name);

return [{
  json: {
    competitor: {
      handle: competitor.username,
      nome: competitor.name || competitor.username,
      tier: 2
    },
    data_referencia: dataRef
  }
}];

const result = $input.first().json;
const handle = result.competitor || 'desconhecido';

if (result.ok) {
  console.log('[IG] ✅ Concluido:', handle, '| Posts:', result.posts_analisados, '| Comentarios:', result.comentarios_analisados);
} else {
  console.error('[IG] ❌ Erro em', handle, ':', result.error || JSON.stringify(result));
}

// Retorna para o loop continuar
return [{ json: { ...result, _loop_tick: new Date().toISOString() } }];

const dataRef = $('Set Data Referencia').first().json.data_referencia;
const total = $input.all().length;

console.log('[IG] ✅ Análise diária concluída para', dataRef, '| Total de concorrentes processados:', total);

return [{ json: { status: 'concluido', data_referencia: dataRef, concorrentes_processados: total, finalizadoEm: new Date().toISOString() } }];

const error = $input.first().json;
console.error('[IG] ERRO NO WORKFLOW:', JSON.stringify(error, null, 2));
// Aqui você pode adicionar notificação por WhatsApp ou email
return [{ json: { erro_registrado: true, detalhe: error } }];
